setup:
@r1 command action=create shape=rectangle name=Roof label="Roof terrace" width=650 height=350 fill=none at=400,250
@r2 command action=create shape=rectangle name=Hatch label="Stair hatch" color=gray size=small position=bottomLeft
@r3 command action=create shape=circle name=Vent label="Vent" color=gray size=small position=topRight

@m1 command action=create shape=rectangle name=Hall label="Entry hall" width=180 height=110 at=330,270
@m2 command action=create shape=square name=Start label="Start" color=green size=small position=below anchor=Hall
@m3 command action=create shape=rectangle name=Exit label="Street exit" color=red size=small position=right
@m4 command action=connect from=Start to=Hall arrow=none

@p1 command action=create shape=rectangle name=Record label="Record" color=blue size=medium position=left
@p2 command action=create shape=rectangle name=Edit label="Edit" color=blue size=medium position=center
@p3 command action=create shape=rectangle name=Publish label="Publish" color=green size=medium position=right
@p4 command action=connect from=Record,Edit,Publish pairing=chain
